#include <iostream>
#include <vector>
using namespace std;

void makePalindrome(int n, vector<long long>& arr) {
    vector<pair<int, long long>> operations;
    int i = 0, j = n - 1;

    while (i < j) {
        if (arr[i] < arr[j]) {
            long long diff = arr[j] - arr[i];
            arr[i] += diff;
            arr[i + 1] += diff;
            operations.push_back({i + 1, diff});
        } else if (arr[i] > arr[j]) {
            long long diff = arr[i] - arr[j];
            arr[j] += diff;
            arr[j - 1] += diff;
            operations.push_back({j, diff});
        }
        i++;
        j--;
    }

    // 检查是否是回文数组
    bool isPalindrome = true;
    for (int k = 0; k < n / 2; k++) {
        if (arr[k] != arr[n - k - 1]) {
            isPalindrome = false;
            break;
        }
    }

    if (isPalindrome) {
        cout << operations.size() << endl;
        for (auto& op : operations) {
            cout << op.first << " " << op.second << endl;
        }
    } else {
        cout << -1 << endl;
    }
}

int main() {
    int n;
    cin >> n;
    vector<long long> arr(n);
    for (int i = 0; i < n; i++) {
        cin >> arr[i];
    }
    makePalindrome(n, arr);
    return 0;
}

